codebase.blog/app.py:
from flask import Flask, render_template_string, request

app = Flask(__name__)
posts = []

@app.route('/')
def index():
    html = '<h1>Blog</h1>'
    for p in posts:
        html += f'<h2>{p["title"]}</h2><p>{p["body"]}</p>'
    return html

@app.route('/post', methods=['POST'])
def create_post():
    title = request.form.get('title', '')
    body = request.form.get('body', '')
    posts.append({'title': title, 'body': body})
    return 'Created', 201

@app.route('/search')
def search():
    q = request.args.get('q', '')
    results = [p for p in posts if q.lower() in p['title'].lower()]
    html = f'<h1>Search: {q}</h1>'
    for p in results:
        html += f'<p>{p["title"]}</p>'
    return html

