def power(base, exp):
    return base ** exp

def sqrt(n):
    if n < 0:
        raise ValueError('Cannot take sqrt of negative')
    return n ** 0.5

def factorial(n):
    if n < 0:
        raise ValueError('Negative factorial')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

